begin;
set local search_path=public,extensions;
grant usage on schema extensions to authenticated;
select no_plan();
insert into auth.users(id,aud,role,email,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
select ('e0380000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'authenticated','authenticated','followup-replay-'||i||'@example.invalid','{}','{}',now(),now() from generate_series(1,2)i;
insert into public.organizations(id,legal_name,display_name,status,created_by) values('e0381000-0000-4000-8000-000000000001','TEST CRM replay','TEST CRM replay','ACTIVE','e0380000-0000-4000-8000-000000000001');
insert into public.organization_memberships(id,organization_id,user_id,status) values('e0382000-0000-4000-8000-000000000001','e0381000-0000-4000-8000-000000000001','e0380000-0000-4000-8000-000000000001','ACTIVE');
insert into public.platform_user_roles(user_id,role_code) values('e0380000-0000-4000-8000-000000000001','MATRICIA_ADMIN');
insert into public.catalog_libraries(id,code,slug,steward_organization_id,created_by) values('e0383000-0000-4000-8000-000000000001','TEST_FOLLOWUP_REPLAY','test-followup-replay','e0381000-0000-4000-8000-000000000001','e0380000-0000-4000-8000-000000000001');
insert into public.franchises(id,library_id,operator_organization_id,franchise_type,operator_code,territory_code,status,created_by) values('e0384000-0000-4000-8000-000000000001','e0383000-0000-4000-8000-000000000001','e0381000-0000-4000-8000-000000000001','STANDARD','FRANCHISEE','TEST_FOLLOWUP_REPLAY','CONTRACT_PENDING','e0380000-0000-4000-8000-000000000001');
insert into public.franchise_territory_versions(id,franchise_id,version,territory_code,name_fr,name_ar,scope_snapshot,effective_from,content_hash,created_by) values('e0385000-0000-4000-8000-000000000001','e0384000-0000-4000-8000-000000000001',1,'TEST_FOLLOWUP_REPLAY','Test','Test','{}',now(),repeat('a',64),'e0380000-0000-4000-8000-000000000001');
insert into public.platform_user_roles(user_id,role_code) values('e0380000-0000-4000-8000-000000000002','MATRICIA_ADMIN');
insert into public.franchise_followup_policy_versions(id,franchise_id,version,status,eligible_stages,reminder_delays_minutes,retry_delays_minutes,maximum_attempts,maximum_reminders_per_7_days,lease_seconds,effective_from,change_reason,content_hash,proposed_by) values('e0386000-0000-4000-8000-000000000001','e0384000-0000-4000-8000-000000000001',1,'PENDING_APPROVAL',array['SENT'],array[0],array[5],2,2,120,now(),'Historical pending policy for replay proof',repeat('b',64),'e0380000-0000-4000-8000-000000000001');
create temporary table followup_results(k text primary key,v jsonb);grant select,insert on followup_results to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"e0380000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2"}',true);
insert into followup_results values('first',public.decide_franchise_followup_policy('e0386000-0000-4000-8000-000000000001','APPROVE','Independent policy review','followup-review-replay','e0387000-0000-4000-8000-000000000001'));
select lives_ok($$insert into followup_results values('replay',public.decide_franchise_followup_policy('e0386000-0000-4000-8000-000000000001','APPROVE','Independent policy review','followup-review-replay','e0387000-0000-4000-8000-000000000001'))$$,'approved decision can be replayed');
select is((select v from followup_results where k='replay'),(select v from followup_results where k='first'),'replay returns exact approval receipt');
select throws_ok($$select public.decide_franchise_followup_policy('e0386000-0000-4000-8000-000000000001','REJECT','Independent policy review','followup-review-replay')$$,'22000','IDEMPOTENCY_PAYLOAD_MISMATCH','same key cannot change the decision');
select throws_ok($$select public.decide_franchise_followup_policy('e0386000-0000-4000-8000-000000000001','REJECT','Independent policy review','followup-review-new')$$,'22023','INVALID_FRANCHISE_FOLLOWUP_POLICY_DECISION','new command cannot decide an already approved policy');
reset role;
select is((select count(*)::integer from public.audit_events a join public.event_outbox e on e.correlation_id=a.correlation_id where a.correlation_id='e0387000-0000-4000-8000-000000000001' and a.action='franchise.followup.policy_decided' and e.event_type='FranchiseFollowupPolicyDecidedV1'),1,'replay preserves one correlated decision');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"e0380000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
select throws_ok($$select public.decide_franchise_followup_policy('e0386000-0000-4000-8000-000000000001','APPROVE','Independent policy review','followup-review-replay')$$,'42501','FRANCHISE_FOLLOWUP_POLICY_DECIDE_DENIED','policy proposer cannot replay an independent approval');
reset role;
select * from finish();rollback;
